-- Migration: Seed V1.0 families, test contract, and contract options
-- Generated by seed_v1_0_migration.py
-- Purpose: Fix e2e test failures (Da Porto feedback model, contract options)

-- ============================================================
-- PART 1: Insert missing families from V1.0
-- ============================================================
ON DUPLICATE KEY UPDATE
  `nombre` = VALUES(`nombre`),
  `categoria` = VALUES(`categoria`),
  `siempre_revision` = VALUES(`siempre_revision`);

-- ============================================================
-- PART 2: Apply test contract (activa/siempre_revision flags)
-- ============================================================
-- 2a. Activate 7 activeListadoFamilies
UPDATE `general_pdc_familias` SET `activa` = 1 WHERE `codigo` IN ('REVOQUE_HUMEDO', 'REVOQUE_SECO', 'CABINAS_BANO', 'CARPINTERIA_METALICA', 'PLANTA_ELECTRICA', 'GRIFERIAS_INCRUSTACIONES', 'ASEO');

-- 2b. Deactivate 4 contractualOnlyFamilies
UPDATE `general_pdc_familias` SET `activa` = 0 WHERE `codigo` IN ('GEODREN', 'MALACATE', 'BOTADA_ESCOMBROS', 'AMENIDADES_CUBIERTA');

-- 2c. Set siempre_revision=1 for 5 reviewFamilies
UPDATE `general_pdc_familias` SET `siempre_revision` = 1 WHERE `codigo` IN ('CAMPAMENTO', 'RED_TELECOMUNICACIONES', 'ASEO', 'BOTADA_ESCOMBROS', 'AMENIDADES_CUBIERTA');

-- ============================================================
-- PART 3: Insert activity rules for families with 0 active rules
-- ============================================================
-- Rules for ENCHAPES
SELECT f.id, '/ENCHAPE|ENCHAPE MUROS|ENCHAPE PAREDES|MANO DE OBRA ENCHAPES/u', 'MO,S', 88, 100, 'Enchapes', 1
FROM `general_pdc_familias` f WHERE f.codigo = 'ENCHAPES';

-- ============================================================
-- PART 4: Insert contract options and items for test contract
-- ============================================================
-- SANITARIOS: Mano de Obra / INSTALACION APARATOS SANITARIOS
SELECT f.id, 1, 'Mano de Obra', 8, 10, 5, 10, 20, 10, 0, 'Contrato test contract para SANITARIOS', 1
FROM `general_pdc_familias` f WHERE f.codigo = 'SANITARIOS';

SELECT o.id, o.tipo_contrato, o.tipo_paquete, 'INSTALACION APARATOS SANITARIOS', 1, 1
FROM `general_pdc_family_contract_options` o
JOIN `general_pdc_familias` f ON f.id = o.familia_id
WHERE f.codigo = 'SANITARIOS' AND o.tipo_paquete = 'Mano de Obra';

